#pragma once

#include <QUrl>

namespace Acheron {
namespace Core {

// Untrusted content may only invoke the link schemes supported by chat.
// Internal client actions are generated by the renderer, never accepted here.
inline bool isAllowedExternalLink(const QUrl &url)
{
    if (!url.isValid() || url.isRelative())
        return false;
    const QString scheme = url.scheme();
    if (scheme == QLatin1String("http") || scheme == QLatin1String("https"))
        return !url.host().isEmpty();
    return scheme == QLatin1String("discord") || scheme == QLatin1String("tel") ||
           scheme == QLatin1String("sms") || scheme == QLatin1String("mailto");
}

inline bool isAllowedWebLink(const QUrl &url)
{
    return isAllowedExternalLink(url) &&
           (url.scheme() == QLatin1String("http") || url.scheme() == QLatin1String("https"));
}

} // namespace Core
} // namespace Acheron
